    Experience = apps.get_model("content", "Experience")

    SiteSettings.objects.update_or_create(pk=1, defaults=SITE_SETTINGS)

    hero_defaults = dict(HERO)
    hero_defaults["photo_data"] = base64.b64decode(HERO_PHOTO_B64)
