    ContactSection.objects.update_or_create(pk=1, defaults=CONTACT)
    AboutSection.objects.update_or_create(pk=1, defaults=ABOUT)

    stack, _ = StackSection.objects.update_or_create(pk=1, defaults={})
    stack.technologies.all().delete()
    Technology.objects.bulk_create(
        [Technology(section=stack, **t) for t in TECHNOLOGIES]
    )

    exp_section, _ = ExperienceSection.objects.update_or_create(
        pk=1, defaults=EXPERIENCE_SECTION
    )
    exp_section.experiences.all().delete()
